import{_ as o,c as r,o as a,a2 as n}from"./chunks/framework.CHomSxuB.js";const _=JSON.parse('{"title":"5. 龙虎榜机构席位：明牌资金没有 alpha（D3 / V0.7）","description":"","frontmatter":{},"headers":[],"relativePath":"A股量化验证/5-龙虎榜机构席位.md","filePath":"A股量化验证/5-龙虎榜机构席位.md"}'),s={name:"A股量化验证/5-龙虎榜机构席位.md"};function d(e,t,l,h,i,g){return a(),r("div",null,t[0]||(t[0]=[n('<h1 id="_5-龙虎榜机构席位-明牌资金没有-alpha-d3-v0-7" tabindex="-1">5. 龙虎榜机构席位：明牌资金没有 alpha（D3 / V0.7） <a class="header-anchor" href="#_5-龙虎榜机构席位-明牌资金没有-alpha-d3-v0-7" aria-label="Permalink to &quot;5. 龙虎榜机构席位：明牌资金没有 alpha（D3 / V0.7）&quot;">​</a></h1><blockquote><p>结论：<strong>龙虎榜&quot;机构净买入&quot;不是建仓动量，是脉冲利好兑现；T+3 持有确定性负超额</strong> —— 双家族 <code>NO_EDGE</code> 卷宗：<code>v0.7_inst_seat_prereg.md</code>（协议 §2.1-2.5 + 探针两本账 + 全量裁决同卷） 产出：<code>bench-d3-20260902.html/json</code>、<code>samples-d3-family{A,B}.csv</code> 这是全系列最&quot;干净&quot;的一次正面证伪——<strong>统计效力足够，方向却反了</strong>，不是&quot;样本不足&quot;。</p></blockquote><h2 id="故事" tabindex="-1">故事 <a class="header-anchor" href="#故事" aria-label="Permalink to &quot;故事&quot;">​</a></h2><p>龙虎榜是交易所公开的&quot;明牌&quot;：哪些席位（机构专用/营业部）在买。流行叙事—— <strong>机构净买入 = 聪明钱建仓</strong>，跟买次日应有超额。这是四条证伪线里唯一的<strong>非价量信息源</strong>， 也是量化圈最难证伪的&quot;资金面神话&quot;之一。</p><h2 id="协议-v0-7-冻结-2026-08-19" tabindex="-1">协议（V0.7 冻结，2026-08-19） <a class="header-anchor" href="#协议-v0-7-冻结-2026-08-19" aria-label="Permalink to &quot;协议（V0.7 冻结，2026-08-19）&quot;">​</a></h2><ul><li>数据：东财龙虎榜机构买卖统计（jgmmtj），243 交易日全量爬取</li><li>家族： <ul><li><strong>Family A</strong> = 纯多头（龙虎榜卖方无机构参与，n_hit=54）</li><li><strong>Family B</strong> = 机构买卖比 ≥ 2（n_hit=99）</li></ul></li><li>判定：T+1 开盘 ≥ 基准×1.095 → UNFILLED 剔除（Family B 剔除 5 只）</li><li>执行：T+1 <strong>开盘价</strong>进场 → T+1/T+2/T+3 收盘离场（三档 horizon）</li><li>摩擦双边 0.35%，超额基准中证 1000，cluster bootstrap ×5000 + BH-FDR Q=0.05</li><li>主端点：<strong>T+3</strong>；n≥30 红线；Pass 门槛：净超额 &gt; +2% 且胜率 &gt; 55% 且 FDR p&lt;0.05</li></ul><h2 id="全量裁决-2026-09-02-243-交易日" tabindex="-1">全量裁决（2026-09-02，243 交易日） <a class="header-anchor" href="#全量裁决-2026-09-02-243-交易日" aria-label="Permalink to &quot;全量裁决（2026-09-02，243 交易日）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>家族</th><th>n</th><th>T+1 净超额</th><th>T+2 净超额</th><th><strong>T+3 净超额（主端点）</strong></th><th>T+3 胜率</th><th>p_boot</th><th>CVaR95</th></tr></thead><tbody><tr><td><strong>A</strong> 纯多头</td><td>54</td><td>+0.24%</td><td>−1.08%</td><td><strong>−1.88%</strong></td><td>37.0%</td><td>0.9454</td><td><strong>−19.46%</strong></td></tr><tr><td><strong>B</strong> 买卖比≥2</td><td>93*</td><td>−0.49%</td><td>−1.06%</td><td><strong>−1.92%</strong></td><td>33.3%</td><td>0.9956</td><td><strong>−15.55%</strong></td></tr></tbody></table><p>* n_hit=99，unfilled 闸剔除 5 只后主端点 n=93。两家族 n 均 ≥30，<strong>统计效力充足</strong>。</p><table tabindex="0"><thead><tr><th>家族</th><th>衰减链（T+1→T+2→T+3）</th><th>FDR</th><th>裁决</th></tr></thead><tbody><tr><td>A</td><td>+0.24% → −1.08% → <strong>−1.88%</strong> 单调恶化</td><td>~1.0</td><td><strong>NO_EDGE</strong></td></tr><tr><td>B</td><td>−0.49% → −1.06% → <strong>−1.92%</strong> 单调恶化</td><td>~1.0</td><td><strong>NO_EDGE</strong></td></tr></tbody></table><h2 id="机理解读-证据-vs-叙事-分清楚" tabindex="-1">机理解读（证据 vs 叙事，分清楚） <a class="header-anchor" href="#机理解读-证据-vs-叙事-分清楚" aria-label="Permalink to &quot;机理解读（证据 vs 叙事，分清楚）&quot;">​</a></h2><p><strong>数据直接支持的（证据）</strong>：</p><ol><li><strong>脉冲快速衰减</strong>——T+1 微弱正脉冲（仅 A 家族 +0.24%）迅速恶化为确定性负超额， &quot;机构持续建仓、越拿越涨&quot;的假设被线性斜率直接推翻；</li><li><strong>下行尾部无托底</strong>——CVaR95 深达 −15%~−19%，&quot;机构票不轻易砸、有下行保护&quot;的经验直觉被证伪。</li></ol><p><strong>数据不支持、纯属推测的（叙事，需另立假设验证）</strong>：</p><ul><li>&quot;龙虎榜 T 日 17:30 公开后已是明牌，次日跟风成了老资金出货的流动性窗口&quot;；</li><li>&quot;机构专用席位已被量化私募/被动配置异化&quot;。 回测只检验了&quot;披露后买入的收益分布&quot;，<strong>无法区分因果机制</strong>——这些是好研究假说，不是裁决结论。</li></ul><h2 id="为什么这次裁决格外可信-方法论价值" tabindex="-1">为什么这次裁决格外可信（方法论价值） <a class="header-anchor" href="#为什么这次裁决格外可信-方法论价值" aria-label="Permalink to &quot;为什么这次裁决格外可信（方法论价值）&quot;">​</a></h2><ol><li><strong>样本密度不是死因</strong>：A n=54、B n=93，双双过 n≥30，统计效力足够；</li><li><strong>p_boot 0.945/0.996 的含义</strong>：在&quot;零假设&quot;下抽到比实际更差结果的概率—— 即这组负收益<strong>显著地差，不是噪声</strong>；</li><li><strong>与探针（n=7）对账一致</strong>：探针预判的&quot;T+3 衰减&quot;头号盯防点被全量坐实，且更差； 命中量落在探针预估区间（A 54 vs 预估≈68；B 99 vs ≈136）——<strong>探针方法论再次有效</strong>。</li></ol><h2 id="系列意义" tabindex="-1">系列意义 <a class="header-anchor" href="#系列意义" aria-label="Permalink to &quot;系列意义&quot;">​</a></h2><p>至此，四条研究线（Step 5 接力 / 情绪闸门 / Step 6 分歧低吸 / D3 机构席位）全部 NO_EDGE， 且 D3 是唯一的<strong>非价量信息源</strong>。全体系收敛为：</p><blockquote><p><strong>散户/游资互掏口袋的价量、情绪、分歧信号：NO_EDGE。 交易所公布的明牌资金席位信号：NO_EDGE。 全系统唯一在回测层有显著 alpha 的底座，依然且仅有：秒级首板先锋（Step 1，前向验证中）。</strong> 别再往&quot;消息面/席位面&quot;上分配研究精力了。</p></blockquote><hr><p><strong>验证线汇总导航</strong>：<a href="/A股量化验证/">返回 A股量化验证 首页</a> · <a href="/A股量化验证/4-分歧低吸.html">上一线：分歧低吸</a> · <a href="/A股量化验证/6-数据洁净度审计.html">下一线：数据洁净度审计</a></p>',22)]))}const q=o(s,[["render",d]]);export{_ as __pageData,q as default};
